from pathlib import Path
from PIL import Image, ImageDraw

from ...utils import resolve_asset_path

ASSETS_DIR = Path(resolve_asset_path("platform/windows/assets"))
STATUS_COLORS = {
    "idle": (40, 190, 80),
    "recording": (235, 55, 55),
    "processing": (245, 195, 35),
    "initializing": (245, 195, 35),
    "unavailable": (140, 140, 140),
}


def with_status_dot(base, state):
    """Keep the microphone artwork; add a compact, ring-free status dot at the top right."""
    image = base.convert("RGBA")
    size = image.size
    scale = 4
    image = image.resize((size[0] * scale, size[1] * scale), Image.Resampling.LANCZOS)
    width, height = image.size
    draw = ImageDraw.Draw(image)
    draw.ellipse((width * .68, height * .04, width * .94, height * .30),
                 fill=STATUS_COLORS.get(state, STATUS_COLORS["unavailable"]))
    return image.resize(size, Image.Resampling.LANCZOS)


def get_tray_icons() -> dict:
    result = {}
    for state in STATUS_COLORS:
        source = "idle"  # Neutral microphone; old recording asset already contains a green dot.
        with Image.open(ASSETS_DIR / ("tray_" + source + ".png")) as base:
            result[state] = with_status_dot(base, state)
    return result
